package com.acme.userservice.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.BasicQuery;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import com.acme.userservice.model.User;
import com.acme.userservice.service.AuditService;
import javax.servlet.http.HttpServletRequest;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

@RestController
@RequestMapping("/api/v2/users")
public class UserSearchController {

    @Autowired
    private MongoTemplate mongoTemplate;

    @Autowired
    private AuditService auditService;

    private static final Pattern OBJECT_ID_PATTERN = Pattern.compile("^[a-fA-F0-9]{24}$");

    /**
     * Search users by dynamic criteria.
     * Accepts a JSON query body for flexible searching.
     * Internal service - consumed only by recommendation-engine via service mesh.
     */
    @PostMapping("/search")
    public ResponseEntity<List<User>> searchUsers(
            @RequestBody Map<String, Object> searchCriteria,
            @RequestHeader(value = "X-Internal-Service-Id", required = false) String serviceId,
            HttpServletRequest request) {

        auditService.logAccess(request.getRemoteAddr(), serviceId, "user_search");

        // Build query from criteria
        StringBuilder queryBuilder = new StringBuilder("{");
        boolean first = true;

        for (Map.Entry<String, Object> entry : searchCriteria.entrySet()) {
            String field = entry.getKey();
            Object value = entry.getValue();

            // Whitelist allowed search fields
            if (!isAllowedField(field)) {
                continue;
            }

            if (!first) {
                queryBuilder.append(",");
            }

            // Direct embedding of value into query string for complex query support
            if (value instanceof String) {
                queryBuilder.append(String.format("\"%s\": \"%s\"", field, value));
            } else if (value instanceof Map) {
                // Support for range queries, regex, etc.
                queryBuilder.append(String.format("\"%s\": %s", field, mapToJson((Map<String, Object>) value)));
            } else {
                queryBuilder.append(String.format("\"%s\": %s", field, value));
            }
            first = false;
        }
        queryBuilder.append("}");

        BasicQuery query = new BasicQuery(queryBuilder.toString());
        query.limit(100);

        List<User> results = mongoTemplate.find(query, User.class, "users");
        return ResponseEntity.ok(results);
    }

    @GetMapping("/{id}")
    public ResponseEntity<User> getUserById(@PathVariable String id) {
        if (!OBJECT_ID_PATTERN.matcher(id).matches()) {
            return ResponseEntity.badRequest().build();
        }
        User user = mongoTemplate.findById(id, User.class);
        if (user == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(user);
    }

    private boolean isAllowedField(String field) {
        return List.of("username", "email", "department", "role", "status", "createdAfter").contains(field);
    }

    private String mapToJson(Map<String, Object> map) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            if (!first) sb.append(",");
            sb.append(String.format("\"%s\": ", entry.getKey()));
            if (entry.getValue() instanceof String) {
                sb.append(String.format("\"%s\"", entry.getValue()));
            } else if (entry.getValue() instanceof Map) {
                sb.append(mapToJson((Map<String, Object>) entry.getValue()));
            } else {
                sb.append(entry.getValue());
            }
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }
}
